/* Loading: built-in window.RT_DATA + ad-hoc FileReader (global script).
   No fetch/XHR local reads (decision B). */
/** Built-in bundle generated by viewer/tools/embed.py (may be absent). */
function builtinData() {
    if (typeof window === "undefined")
        return null;
    return window.RT_DATA ?? null;
}
/** Read a JSON file object chosen via <input type="file">. */
function readJsonFile(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onerror = () => reject(new Error(t("err.fileread")));
        reader.onload = () => {
            try {
                resolve(JSON.parse(String(reader.result)));
            }
            catch (e) {
                reject(new Error(t("err.json", String(e))));
            }
        };
        reader.readAsText(file);
    });
}
/** Load an ad-hoc run log chosen via <input type="file">. */
function loadLogFile(file) {
    return readJsonFile(file).then((doc) => {
        const bad = validateLogForPlayback(doc);
        if (bad)
            throw new Error(bad);
        return doc;
    });
}
/** Load an ad-hoc puzzle.json chosen via <input type="file">. */
function loadPuzzleFile(file) {
    return readJsonFile(file).then((doc) => doc);
}
/* Floor grouping by cell prefix (global script). Prefix-less cells attach
   to the single floor. Group-visibility switching shows only the active
   floor's moves and observations. */
/** "2F-C4" -> "2F", "C4" -> "". */
function floorKeyOfCell(cell) {
    const dash = cell.indexOf("-");
    return dash >= 0 ? cell.slice(0, dash) : "";
}
/** Floor key for a spatial event, null for floor-agnostic events. */
function eventFloor(e) {
    if (e.type === "move")
        return floorKeyOfCell(e.value);
    if (e.type === "view") {
        const v = e.value;
        const at = v.indexOf("@");
        return floorKeyOfCell(at >= 0 ? v.slice(at + 1) : v);
    }
    return null;
}
/** Floors present in the log (start cell first), in order of appearance. */
function logFloors(log, startCell) {
    const out = [];
    const push = (key) => {
        if (out.indexOf(key) < 0)
            out.push(key);
    };
    push(floorKeyOfCell(startCell));
    for (const e of log.events) {
        const f = eventFloor(e);
        if (f !== null)
            push(f);
    }
    return out;
}
/** Match a floor key to a space floor (prefix-less goes to the single floor). */
function floorForKey(space, key) {
    if (!space.floors.length)
        return null;
    if (key === "")
        return space.floors[0];
    for (const floor of space.floors) {
        if (floor.id === key)
            return floor;
    }
    return null;
}
